import { Overlay } from '@alifd/next';

class Demo extends React.Component {
    constructor(props) {
        super(props);

        this.state = {
            visible: true
        };
    }

    render() {
        return (
            <div>
                <Overlay visible={this.state.visible} align="tc tc" wrapperStyle={{ width: 'auto' }}>
                    <span className="overlay-demo">
                        Will be closed after 3 seconds or manually click on the close button
                    </span>
                </Overlay>
            </div>
        );
    }
}

ReactDOM.render(<Demo />, mountNode);
